def split_date(text):
    """Split a date string into year, month and day strings."""
    cleaned = text.strip()
    if "-" in cleaned:
        year, month, day = cleaned.split("-")
    elif "/" in cleaned:
        year, month, day = cleaned.split("/")
    elif "." in cleaned:
        day, month, year = cleaned.split(".")
    else:
        raise ValueError(f"Unsupported date format: {text}")
    return year, month, day


def parse_date(text):
    """Parse an import date into a (year, month, day) tuple of ints."""
